#include <bits/stdc++.h>
using namespace std;

bool perfect(long long n) {
    int sum = 0;
    while (n != 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum == 10;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    while (cin >> n) {
        for (long long i = 1;; ++i) {
            if (perfect(i) && --n == 0) {
                cout << i << '\n';
                break;
            }
        }
    }
    return 0;
}

